        return [best_idx, max_ones]

class Solution {
public:
    std::vector<int> rowAndMaximumOnes(std::vector<std::vector<int>>& mat) {
        int best_idx = 0, max_ones = -1;
        for (int i = 0; i < (int)mat.size(); i++) {
            int c = 0;
            for (int val : mat[i]) if (val == 1) c++;
            if (c > max_ones) {
                max_ones = c;
                best_idx = i;
            }
        }
        return {best_idx, max_ones};
    }
};

class Solution {
    public int[] rowAndMaximumOnes(int[][] mat) {
        int bestIdx = 0, maxOnes = -1;
        for (int i = 0; i < mat.length; i++) {
            int c = 0;
            for (int val : mat[i]) if (val == 1) c++;
            if (c > maxOnes) {
                maxOnes = c;
                bestIdx = i;
            }
        }
        return new int[]{bestIdx, maxOnes};
    }
}

var rowAndMaximumOnes = function(mat) {
    let bestIdx = 0, maxOnes = -1;
    for (let i = 0; i < mat.length; i++) {
        let c = 0;
        for (const val of mat[i]) {
            if (val === 1) c++;
        }
        if (c > maxOnes) {
            maxOnes = c;
            bestIdx = i;
        }
    }
    return [bestIdx, maxOnes];
};
